"""Checks of notebooks/01_smoke_test_colab.ipynb as generated by scripts/build_notebook_01.py.

No kernel is started and nothing touches models, CUDA, the network or data/raw: the builder writes into tmp_path, the
notebook is inspected with nbformat + ast, the pure helper cell (1b) is executed in a plain namespace, and the privacy
(4) and VIN (6) cells are executed against stubs (anonymiser, OCR engines, vPIC) on synthetic images in tmp_path.
"""

from __future__ import annotations

import ast
import json
import re
import subprocess
import sys
from pathlib import Path
from types import SimpleNamespace
from typing import Any

import cv2
import nbformat
import numpy as np
import pytest

ROOT = Path(__file__).resolve().parents[1]
BUILDER = ROOT / "scripts" / "build_notebook_01.py"
COMMITTED = ROOT / "notebooks" / "01_smoke_test_colab.ipynb"
SAMPLE_VIN = "1HGCM82633A004352"  # public sample VIN (49 CFR 565 / NHTSA examples), not a scanned car

# calls that would show or persist pixels
DISPLAY_NAMES = {"display", "imshow", "save_jpeg", "imwrite"}
DISPLAY_ATTRS = {"imshow", "imwrite", "save_jpeg", "savefig", "show", "fromarray", "download"}


def run_builder(*args: str) -> subprocess.CompletedProcess:
    return subprocess.run([sys.executable, str(BUILDER), *args], cwd=ROOT, capture_output=True, text=True,
                          timeout=120)


@pytest.fixture(scope="module")
def nb_path(tmp_path_factory: pytest.TempPathFactory) -> Path:
    out = tmp_path_factory.mktemp("nb") / "01_smoke_test_colab.ipynb"
    proc = run_builder("--out", str(out))
    assert proc.returncode == 0, proc.stderr
    return out


@pytest.fixture(scope="module")
def nb(nb_path: Path) -> nbformat.NotebookNode:
    return nbformat.read(nb_path, as_version=4)


def code_cells(nb: nbformat.NotebookNode) -> list[Any]:
    return [c for c in nb.cells if c.cell_type == "code"]


def tagged(nb: nbformat.NotebookNode, tag: str) -> Any:
    found = [c for c in code_cells(nb) if tag in c.metadata.get("tags", [])]
    assert len(found) == 1, f"expected one code cell tagged {tag!r}"
    return found[0]


def calls(tree: ast.AST) -> list[ast.Call]:
    return [n for n in ast.walk(tree) if isinstance(n, ast.Call)]


def call_name(call: ast.Call) -> str | None:
    f = call.func
    return f.id if isinstance(f, ast.Name) else f.attr if isinstance(f, ast.Attribute) else None


# ------------------------------------------------------------------------------------------- structure

def test_valid_nbformat_v4_python3_kernel(nb: nbformat.NotebookNode) -> None:
    nbformat.validate(nb)
    assert nb.nbformat == 4
    assert nb.metadata["kernelspec"]["name"] == "python3"
    assert nb.metadata["kernelspec"]["language"] == "python"


def test_no_outputs_and_no_execution_counts(nb: nbformat.NotebookNode) -> None:
    for cell in code_cells(nb):
        assert cell.outputs == [], cell.id
        assert cell.execution_count is None, cell.id


def test_markdown_cell_before_every_code_cell(nb: nbformat.NotebookNode) -> None:
    assert nb.cells[0].cell_type == "markdown"
    for prev, cell in zip(nb.cells, nb.cells[1:]):
        if cell.cell_type == "code":
            assert prev.cell_type == "markdown", f"{cell.id} has no markdown cell before it"


def test_every_code_cell_parses(nb: nbformat.NotebookNode) -> None:
    for cell in code_cells(nb):
        ast.parse(cell.source, filename=cell.id)


def test_build_is_deterministic(nb_path: Path, tmp_path: Path) -> None:
    again = tmp_path / "again.ipynb"
    assert run_builder("--out", str(again)).returncode == 0
    assert again.read_bytes() == nb_path.read_bytes()
    ids = [c.id for c in nbformat.read(again, as_version=4).cells]
    assert len(ids) == len(set(ids))


def test_committed_notebook_is_up_to_date() -> None:
    proc = run_builder("--check", "--out", str(COMMITTED))
    assert proc.returncode == 0, proc.stderr or proc.stdout


# ------------------------------------------------------------------------------------------- safety rules

def test_yolo_autoinstall_forced_in_cell_1_before_any_ultralytics_import(nb: nbformat.NotebookNode) -> None:
    first = code_cells(nb)[0]
    setter = 'os.environ["YOLO_AUTOINSTALL"] = "false"'
    assert setter in first.source, "cell 1 must force YOLO_AUTOINSTALL=false"
    all_code = "\n".join(c.source for c in code_cells(nb))
    # a default (setdefault) would keep YOLO_AUTOINSTALL=true from the environment: ultralytics' patched
    # PIL.Image.open then pip-installs pi-heif the first time an image fails to open
    assert 'setdefault("YOLO_AUTOINSTALL"' not in all_code
    imports = [m.start() for m in re.finditer(r"^\s*(import ultralytics|from ultralytics)", all_code, re.M)]
    assert imports, "the notebook is expected to import ultralytics"
    assert all_code.index(setter) < min(imports)


def test_overrides_accept_avto_settings_only(nb: nbformat.NotebookNode) -> None:
    config = tagged(nb, "config").source
    loop = config.index("for key, value in OVERRIDES.items():")
    assert 'startswith("AVTO_")' in config[loop:config.index("os.environ[key] = str(value)")]
    tree = ast.parse(tagged(nb, "env").source)
    autoinstall_checks = [n for n in ast.walk(tree) if isinstance(n, ast.If)
                          and isinstance(n.test, ast.Name) and n.test.id == "ULTRALYTICS_AUTOINSTALL"]
    assert autoinstall_checks and all(isinstance(n.body[0], ast.Raise) for n in autoinstall_checks)


def test_nothing_displayed_or_saved_up_to_the_privacy_cell(nb: nbformat.NotebookNode) -> None:
    cells = code_cells(nb)
    privacy = cells.index(tagged(nb, "privacy"))
    for cell in cells[: privacy + 1]:
        tree = ast.parse(cell.source)
        for call in calls(tree):
            f = call.func
            assert not (isinstance(f, ast.Name) and f.id in DISPLAY_NAMES), f"{cell.id}: {f.id}()"
            assert not (isinstance(f, ast.Attribute) and f.attr in DISPLAY_ATTRS), f"{cell.id}: .{f.attr}()"
        for node in ast.walk(tree):
            assert not (isinstance(node, ast.Name) and node.id == "plt"), f"{cell.id} uses plt"
            if isinstance(node, (ast.Import, ast.ImportFrom)):
                mods = [node.module or ""] if isinstance(node, ast.ImportFrom) else [a.name for a in node.names]
                assert not any(m.startswith(("matplotlib", "IPython.display")) for m in mods), cell.id


def test_privacy_cell_builds_anonymizer_before_decoding_and_fails_closed(nb: nbformat.NotebookNode) -> None:
    tree = ast.parse(tagged(nb, "privacy").source)
    in_functions = {id(n) for f in tree.body if isinstance(f, ast.FunctionDef) for n in ast.walk(f)}
    top_calls = [c for c in calls(tree) if id(c) not in in_functions]
    anon = [c.lineno for c in top_calls if call_name(c) == "Anonymizer"]
    decoding = [c.lineno for c in top_calls
                if call_name(c) in {"process_video", "process_photo", "load_image", "extract_frames"}]
    assert anon and decoding and max(anon) < min(decoding)
    handlers = [h for h in ast.walk(tree) if isinstance(h, ast.ExceptHandler)
                and isinstance(h.type, ast.Name) and h.type.id == "PrivacyUnavailable"]
    assert handlers and all(any(isinstance(n, ast.Raise) for n in ast.walk(h)) for h in handlers)


def test_vin_cell_prints_only_through_the_guard_and_never_caches(nb: nbformat.NotebookNode) -> None:
    tree = ast.parse(tagged(nb, "vin").source)
    names = [call_name(c) for c in calls(tree)]
    assert "print" not in names and "display" not in names
    decodes = [c for c in calls(tree) if call_name(c) == "decode"]
    assert decodes
    for call in decodes:
        kw = {k.arg: k.value for k in call.keywords}
        assert isinstance(kw.get("cache_dir"), ast.Constant) and kw["cache_dir"].value is None


def test_files_are_written_only_through_guarded_helpers(nb: nbformat.NotebookNode) -> None:
    for cell in code_cells(nb):
        if {"bootstrap", "helpers"} & set(cell.metadata.get("tags", [])):
            continue
        for call in calls(ast.parse(cell.source)):
            f = call.func
            assert not (isinstance(f, ast.Attribute) and f.attr in {"write_text", "write_bytes"}), cell.id
            assert not (isinstance(f, ast.Attribute) and f.attr == "dump"
                        and isinstance(f.value, ast.Name) and f.value.id == "json"), cell.id
            if isinstance(f, ast.Name) and f.id == "open":
                modes = [a.value for a in call.args[1:2] if isinstance(a, ast.Constant)]
                modes += [k.value.value for k in call.keywords if k.arg == "mode" and isinstance(k.value, ast.Constant)]
                assert not any(set(str(m)) & set("wax") for m in modes), cell.id


# ------------------------------------------------------------------------------------------- contracts

def _literal_assign(source: str, name: str) -> Any:
    for node in ast.walk(ast.parse(source)):
        if isinstance(node, ast.Assign) and any(isinstance(t, ast.Name) and t.id == name for t in node.targets):
            return ast.literal_eval(node.value)
        if isinstance(node, ast.AnnAssign) and isinstance(node.target, ast.Name) and node.target.id == name:
            return ast.literal_eval(node.value)
    raise KeyError(name)


def test_latency_columns_match_the_bench_script(nb: nbformat.NotebookNode) -> None:
    bench = ROOT / "scripts" / "bench_cpu.py"
    if not bench.is_file():
        pytest.skip("scripts/bench_cpu.py not written yet")
    source = bench.read_text(encoding="utf-8")
    assert list(_literal_assign(tagged(nb, "latency").source, "LAT_FIELDS")) == list(_literal_assign(source, "FIELDS"))
    for flag in ("--onnx", "--model-key", "--imgsz", "--task", "--frames-dir", "--threads", "--warmup", "--runs",
                 "--cap-s", "--run", "--pinned", "--out"):
        assert f'"{flag}"' in source, flag


def test_model_keys_and_files_match_download_script(nb: nbformat.NotebookNode) -> None:
    source = (ROOT / "scripts" / "download_models.py").read_text(encoding="utf-8")
    local = {}  # key -> "models/<local>"
    for call in calls(ast.parse(source)):
        if call_name(call) == "ModelFile" and len(call.args) >= 5:
            key, rel = ast.literal_eval(call.args[0]), ast.literal_eval(call.args[4])
            local[key] = f"models/{rel}"
    models_src = tagged(nb, "models").source
    for key in ("damage_mitbersh", "damage_danishali", "damage_harpreet", "parts_mitbersh", "coco_yolo26n"):
        assert key in local, key
        assert f'"{local[key]}"' in models_src, f"{key}: notebook path differs from {local[key]}"
    for key in _literal_assign(models_src, "PRIVACY_FILES") + ("damage_mitbersh_config", "parts_mitbersh_config"):
        assert key in local, key
    assert '"models/plate/license-plate-finetune-v1n.onnx"' in tagged(nb, "latency").source
    assert local["plate_n_onnx"] == "models/plate/license-plate-finetune-v1n.onnx"


