def test_ground_truth_matching(h: SimpleNamespace) -> None:
    gt = h.ground_truth_map([{"FILE ": " data/raw/vin/VIN_A.jpg", "Vin": f" {SAMPLE_VIN[:8]} {SAMPLE_VIN[8:]} "},
                             {"file": "vin_b.JPG", "vin": SAMPLE_VIN.lower()}, {"file": "", "vin": SAMPLE_VIN},
                             {"file": "VIN_C.jpg", "vin": None}])
    assert gt == {"vin_a.jpg": SAMPLE_VIN, "vin_b.jpg": SAMPLE_VIN}
    assert h.gt_key(gt, "VIN_A.jpg") == "vin_a.jpg"
    assert h.gt_key(gt, "VIN_B.jpg") == "vin_b.jpg"  # case-insensitive
    assert h.gt_key(gt, "vin_a.png") == "vin_a.jpg"  # same stem
    assert h.gt_key(gt, "VIN_C.jpg") is None


