def test_privacy_cell_keeps_only_anonymised_copies(
        nb: nbformat.NotebookNode, tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> None:
    import avtopassport.pipeline.privacy as privacy

    calls: list[tuple[int, ...]] = []

    class StubAnonymizer:
        def __init__(self, *, device: str, extra_detectors: Any) -> None:
            assert device == "cpu" and len(extra_detectors) == 2  # parts-model plate class + COCO person-head band

        def anonymize(self, img: np.ndarray) -> tuple[np.ndarray | None, Any]:
            calls.append(img.shape)
            if len(calls) == 2:
                return None, privacy.PrivacyReport(ok=False, errors=["detector failed"])
            if len(calls) == 3:
                raise RuntimeError("detector crashed")
            return np.full_like(img, 7), privacy.PrivacyReport(ok=True, n_plates=1, passes={"stub": 1})

    monkeypatch.setattr(privacy, "Anonymizer", StubAnonymizer)
    ns = _run_state(nb, tmp_path)
    for name in ("P1.png", "P2.png", "P3.png"):
        cv2.imwrite(str(ns["RAW"] / "images" / name), np.full((40, 60, 3), 200, np.uint8))
    ns["PRIVACY_PARTS"] = SimpleNamespace(names={0: "license-plate"})
    ns["PRIVACY_COCO"] = SimpleNamespace(names={0: "person"})
    exec(compile(tagged(nb, "privacy").source, "privacy", "exec"), ns)
    assert calls == [(40, 60, 3)] * 3  # full-resolution photos went through the anonymiser
    assert [b["file"] for b in ns["BLURRED_PHOTOS"]] == ["P1.png"] and (ns["BLURRED_PHOTOS"][0]["image"] == 7).all()
    assert ns["COUNTS"]["photos_dropped_privacy"] == 2 and ns["COUNTS"]["model_inputs"] == 1
    assert [r["ok"] for r in ns["PRIVACY_ROWS"]] == [True, False, False]
    assert [e["stage"] for e in ns["ERRORS"]] == ["privacy"]
    assert sorted(p.name for p in ns["OUT"].iterdir()) == ["frames_quality.csv", "privacy.json"]  # no pixels


def test_vin_cell_masks_everything_it_writes_and_prints(
        nb: nbformat.NotebookNode, tmp_path: Path, monkeypatch: pytest.MonkeyPatch,
        capsys: pytest.CaptureFixture[str]) -> None:
    import avtopassport.io as aio
    import avtopassport.vin.decode as vdec
    import avtopassport.vin.ocr as vocr

    named = "XWB3L32EDKA123456"  # VIN-like token in the name of a photo that fails to load
    script = {1: [(f"VIN {SAMPLE_VIN}", 0.95)],
              2: [("1HGCM82633A0O43S2", 0.9)],  # O at 13 and S at 16 are corrected: tail characters
              3: [("NO VIN HERE", 0.8)]}

    def read_vin(image: np.ndarray, *, engine: Any = None, known_wmis: Any = None, **kw: Any) -> Any:
        return vocr._vin_from_lines(script[int(image[0, 0, 0])], known_wmis=known_wmis, prefix="rot0",
                                    engine="rapidocr")

    def decode(vin: str, *, use_vpic: bool = True, timeout: float = 4.0, cache_dir: Any = vdec.VPIC_CACHE,
               table_path: Path = vdec.WMI_TABLE) -> Any:
        assert cache_dir is None, "a vPIC cache file would hold the unmasked VIN"
        return vdec.VinDecode(vin=vin, wmi=vin[:3], notes=[f"vPIC echo {vin}"], vpic_error_text=f"bad {vin.lower()}")

    def box(y: float) -> list[list[float]]:
        return [[0, y], [80, y], [80, y + 10], [0, y + 10]]

    class Reader:
        def __init__(self, langs: list[str], gpu: bool = False, verbose: bool = False) -> None:
            pass

        def readtext(self, img: np.ndarray, allowlist: str | None = None) -> list[tuple[Any, str, float]]:
            idx = int(img[0, 0, 0])
            if idx == 1:  # the VIN split over two lines, bottom line detected first
                return [(box(50), SAMPLE_VIN[11:], 0.8), (box(0), SAMPLE_VIN[:11], 0.9)]
            if idx == 2:  # mandatory check digit fails
                return [(box(0), SAMPLE_VIN[:-1] + "3", 0.7)]
            return []

    monkeypatch.setattr(vocr, "read_vin", read_vin)
    monkeypatch.setattr(vocr, "make_engine", lambda *a, **k: object())
    monkeypatch.setattr(vdec, "decode", decode)
    monkeypatch.setitem(sys.modules, "easyocr", SimpleNamespace(Reader=Reader))
    ns = _run_state(nb, tmp_path)
    exec(compile(_function_source(tagged(nb, "privacy").source, "list_media"), "privacy", "exec"), ns)
    vin_dir = ns["RAW"] / "vin"
    for idx, name in ((1, "VIN_A.png"), (2, "VIN_B.png"), (3, "VIN_C.png")):
        img = np.full((20, 80, 3), 255, np.uint8)
        img[0, 0] = idx  # selects the scripted OCR text (PNG: lossless)
        cv2.imwrite(str(vin_dir / name), img)
    (vin_dir / f"{named}.jpg").write_bytes(b"")
    (vin_dir / "ground_truth.csv").write_text(
        f"﻿FILE,VIN\nVIN_A.png,{SAMPLE_VIN}\nvin_b.PNG,{SAMPLE_VIN}\n{named}.jpg,{named}\nmissing.jpg,{SAMPLE_VIN}\n",
        encoding="utf-8")

    def load_image(path: Path, **kw: Any) -> np.ndarray:
        if Path(path).stem == named:
            raise ValueError(f"cannot decode image {path}")
        return aio.load_image(path, **kw)

    ns["load_image"] = load_image
    exec(compile(tagged(nb, "vin").source, "vin", "exec"), ns)

    text = (ns["OUT"] / "vin_results.json").read_text(encoding="utf-8")
    for blob in (text, capsys.readouterr().out, json.dumps(ns["ERRORS"])):
        assert SAMPLE_VIN not in blob.upper() and named not in blob.upper()
        assert not re.search(r"pos 1[2-7]: [^*]", blob), "a correction reveals a masked character"
    assert [p.name for p in ns["OUT"].iterdir()] == ["vin_results.json"]
    res = json.loads(text)
    rapid = {r["file"]: r for r in res["results"]}
    easy = {r["file"]: r for r in res["easyocr_results"]}
    assert rapid["VIN_A.png"]["status"] == "read" and rapid["VIN_A.png"]["vin_masked"] == "1HGCM82633A******"
    assert rapid["VIN_A.png"]["exact_match"] is True
    assert "vPIC echo 1HGCM82633A******" in rapid["VIN_A.png"]["decode"]["notes"]
    assert rapid["VIN_B.png"]["exact_match"] is True  # ground truth listed as vin_b.PNG
    assert rapid["VIN_B.png"]["corrections"] == ["pos 13: *->*", "pos 16: *->*"]
    assert rapid["VIN_C.png"]["status"] == "could_not_read" and rapid["VIN_C.png"]["ocr_reasons"]
    assert rapid["XWB3L32EDKA******.jpg"]["status"] == "error"
    # EasyOCR goes through read_vin's own rules: lines in reading order are stitched; a failing check digit is no read
    assert easy["VIN_A.png"]["status"] == "read" and easy["VIN_A.png"]["exact_match"] is True
    assert easy["VIN_A.png"]["source"] == "easyocr/line1+2"
    assert easy["VIN_B.png"]["exact_match"] is False
    assert all(r["validation_status"] in ("valid", "valid_unverified") for r in easy.values() if r["status"] == "read")
    assert res["ground_truth_unmatched_rows"] == 1
    assert (res["n_read"], res["n_exact"], res["easyocr_n_exact"]) == (2, 2, 1)
    assert not ns["GROUND_TRUTH"] and ns["COUNTS"]["vin_images"] == 4


def test_summary_cell_scrubs_results_before_writing(nb: nbformat.NotebookNode) -> None:
    tree = ast.parse(tagged(nb, "summary").source)
    assigns = [n for n in tree.body if isinstance(n, ast.Assign) and any(
        isinstance(t, ast.Name) and t.id == "RESULTS" for t in n.targets)]
    assert assigns and all(isinstance(a.value, ast.Call) and call_name(a.value) == "scrub_obj" for a in assigns)
